results.cypher:
MATCH (r:Road)
WHERE NOT EXISTS { 
  MATCH (e:Entity)-[:ON_ROAD]->(r) 
  RETURN e 
}
RETURN r.id AS id, r.name AS name, r.status AS status, r.status_since AS status_since, r.source AS source, r.confidence AS confidence, r.raw_evidence_ref AS raw_evidence_ref, r.conflict AS conflict, r.conflict_claim AS conflict_claim, r.conflict_source AS conflict_source LIMIT 25
